<?php require 'includes/functions.php';require_login();$q=db()->prepare('SELECT * FROM orders WHERE id=? AND user_id=?');$q->execute([(int)($_GET['id']??0),user()['id']]);$o=$q->fetch();if(!$o)go('orders.php');$steps=['pending'=>'Order Placed','confirmed'=>'Confirmed','packed'=>'Packed','shipped'=>'Shipped','out_for_delivery'=>'Out for Delivery','delivered'=>'Delivered'];$current=array_search($o['order_status'],array_keys($steps));$pageTitle='Track Order';require 'includes/header.php';require 'includes/navbar.php'; ?><main class="container my-5" style="max-width:700px"><h1 class="section-title">Track <?=e($o['order_number'])?></h1><div class="card card-body"><?php foreach($steps as $key=>$label): $index=array_search($key,array_keys($steps)); ?><div class="d-flex align-items-center gap-3 py-2 <?=$index<=$current?'fw-bold':''?>"><span class="rounded-circle d-inline-flex justify-content-center align-items-center <?=$index<=$current?'bg-dark text-white':'border'?>" style="width:32px;height:32px"><?=$index<=$current?'✓':$index+1?></span><?=e($label)?></div><?php endforeach ?></div></main><?php require 'includes/footer.php'; ?>
